const dialog=$('#detail-dialog'),content=$('#dialog-content');let lastFocus;
function openDialog(html,cls=''){lastFocus=document.activeElement;content.innerHTML=html;dialog.className=cls;dialog.showModal();document.body.classList.add('modal-open');dialog.scrollTop=0;$('.dialog-close').focus()}
function closeDialog(){dialog.close()}
dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');lastFocus?.focus()});$('.dialog-close').onclick=closeDialog;dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
function renderTeam(filter='all'){const members=team.filter(t=>filter==='all'||t[3]===filter);$('#team-grid').innerHTML=members.map(t=>`<button class="team-card reveal" data-person="${t[2]}" aria-label="Meet ${t[0]}, ${t[1]}"><div class="team-photo"><img src="/assets/team/${t[2]}.jpg" alt="${t[0]}’s official BMETT introduction card" width="1080" height="1080" loading="lazy"><span aria-hidden="true">↗</span></div><h3>${t[0]}</h3><p>${t[1]}</p></button>`).join('');$$('[data-person]').forEach(b=>b.onclick=()=>{let t=team.find(t=>t[2]===b.dataset.person),slide=team.indexOf(t)+2;openDialog(`<div class="portrait-dialog"><img class="dialog-image" src="/assets/team/${t[2]}.jpg" alt="Official BMETT introduction for ${t[0]}"><p class="dialog-kicker">2026–27 / ${t[1].toUpperCase()}</p><h2 id="dialog-title" class="dialog-title">${t[0]}</h2><p class="dialog-body">${t[1]} · McMaster Biomedical Engineering Technical Team</p><div class="dialog-actions"><a class="text-link" target="_blank" rel="noopener" href="https://www.instagram.com/mcmasterbmett/p/Dek9Lr3lJKx/?img_index=${slide}">View the official introduction ↗</a></div></div>`,'portrait-view')})}
$$('[data-team-filter]').forEach(b=>b.onclick=()=>{$$('[data-team-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderTeam(b.dataset.teamFilter)});renderTeam();
function renderEvents(filter='upcoming'){$('#event-list').innerHTML=events.filter(e=>e.filter===filter).map(e=>`<button class="event-row reveal" data-event="${e.id}" aria-label="Details for ${e.title}"><div class="event-date">${e.day}<small>${e.month}</small></div><div class="event-info"><h3>${e.title}</h3><p>${e.subtitle}</p></div><div class="event-meta">${e.id==='cubec-next'?'January 31 · Interest list':e.date}<br>${e.place}</div><span class="event-arrow" aria-hidden="true">↗</span></button>`).join('');$$('[data-event]').forEach(b=>b.onclick=()=>{let e=events.find(e=>e.id===b.dataset.event);openDialog(`<p class="dialog-kicker">${e.filter==='past'?'PAST HIGHLIGHT':'WHAT’S ON'} / ${e.category}</p><h2 id="dialog-title" class="dialog-title">${e.title}</h2><p class="dialog-body">${e.body}</p><div class="dialog-meta"><strong>${e.date}</strong><br>${e.place}</div><div class="dialog-actions"><a class="button" target="_blank" rel="noopener" href="${e.link}">${e.label} <span>↗</span></a>${e.calendar?'<a class="text-link" href="'+(typeof e.calendar==='string'?e.calendar:'/bmett-3d-printing.ics')+'" download>Add to calendar ↓</a>':''}</div>${e.source?`<p class="small" style="margin-top:25px">Details from BMETT’s official channels. <a href="${e.source}" target="_blank" rel="noopener" style="text-decoration:underline">Original announcement ↗</a></p>`:''}`)})}
$$('[data-event-filter]').forEach(b=>b.onclick=()=>{$$('[data-event-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderEvents(b.dataset.eventFilter)});renderEvents();
function selectFeature(b){$$('[data-feature]').forEach(x=>{x.setAttribute('aria-selected',String(x===b));x.tabIndex=x===b?0:-1});let f=features[b.dataset.feature];$('#project-panel').innerHTML=`<h3>${f[0]}</h3><p>${f[1]}</p>`;$('#project-panel').setAttribute('aria-labelledby',b.id)}
$$('[data-feature]').forEach((b,i)=>{b.onclick=()=>selectFeature(b);b.onkeydown=e=>{let tabs=$$('[data-feature]'),n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;else if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=tabs.length-1;else return;e.preventDefault();selectFeature(tabs[n]);tabs[n].focus()}});
