$('[data-sources]').onclick=()=>openDialog(`<p class="dialog-kicker">INFORMATION & IMAGERY</p><h2 id="dialog-title" class="dialog-title">Sources & photo credits</h2><div class="source-list"><p>The December 3 workshop details were supplied for this site, with the date confirmed on November 26, 2026. Other information was checked November 4, 2026. We reviewed the 12 publicly accessible Instagram posts from September 24–November 2 and all 17 slides in the current leadership introduction. Older posts and story highlights required login.</p><p>The logo was supplied for this site. Leadership cards come from <a target="_blank" rel="noopener" href="https://www.instagram.com/mcmasterbmett/">@mcmasterbmett</a>. Project and group photography comes from <a target="_blank" rel="noopener" href="https://www.linkedin.com/company/mcmasterbmett/">BMETT’s official LinkedIn</a>. Supporter logos were obtained from each organization’s official website or social profile. Sponsor names acknowledge support reported in the 2025–26 season recap; they do not imply a current sponsorship agreement.</p><ul><li><a target="_blank" rel="noopener" href="https://www.instagram.com/mcmasterbmett/p/Dek9Lr3lJKx/">2026–27 leadership introduction</a></li><li><a target="_blank" rel="noopener" href="https://www.linkedin.com/feed/update/urn:li:activity:7447005535897509888/">TrACL & 2025–26 season recap</a></li><li><a target="_blank" rel="noopener" href="https://ahmedzafar.ca/blog/bmett">TrACL technical write-up by Ahmed Zafar</a></li><li><a target="_blank" rel="noopener" href="https://forms.gle/jDjvBEvvGYVyDpYc8">Fall 2026 member applications (closed)</a></li><li><a target="_blank" rel="noopener" href="https://forms.gle/86vmrfNZ3bk8VDDv5">2026–27 lead applications (closed)</a></li><li><a target="_blank" rel="noopener" href="https://linktr.ee/mcmasterbmett">Current BMETT links</a></li></ul><p>Event dates, rooms, and availability may change. Events link to their original announcement or organizer where available.</p></div>`);
const menu=$('.menu-toggle'),nav=$('#navigation');menu.onclick=()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open)};$$('a',nav).forEach(a=>a.onclick=()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation')});document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});
const observer=new IntersectionObserver(entries=>{for(const e of entries){if(e.isIntersecting){$$('nav a').forEach(a=>a.classList.toggle('current',a.getAttribute('href')==='#'+e.target.id))}}},{rootMargin:'-15% 0px -60% 0px'});$$('main section[id]').forEach(s=>observer.observe(s));
